SELECT unique_id, config_id, polygon_id, monitor_area_id
FROM vm_polygon_patch_algo_area_rela ppa
where ppa.delete_flag = 0

    AND ppa.config_id = #{configId}


    AND ppa.polygon_id = #{polygonId}


    AND ppa.monitor_area_id = #{monitorAreaId}


    AND ppa.polygon_id in

        #{item}

SELECT ppa.unique_id,ppa.config_id,ppa.polygon_id,ppa.monitor_area_id,pc.polygon_points,pc.layer_id,pc.feature_id,pc.tbbh
FROM vm_polygon_patch_algo_area_rela ppa
    LEFT JOIN vm_algorithm_config vac ON ppa.config_id = vac.config_id
    LEFT JOIN vm_polygon_patch_config pc ON ppa.polygon_id = pc.polygon_id
WHERE ppa.delete_flag = 0 AND pc.delete_flag = 0  AND vac.delete_flag = 0

    AND ppa.config_id = #{configId}


    AND ppa.polygon_id = #{polygonId}


    AND ppa.monitor_area_id = #{monitorAreaId}


    AND ppa.polygon_id in

        #{item}



    AND ppa.config_id in

        #{id}


${dataPermissions}
